  cycle_nudge_follicular_hydrate_headline: "*Servikal mukusuna* dikkat et",
  cycle_nudge_follicular_hydrate_body: "Pencere yaklaştıkça daha şeffaf ve daha uzayan bir hâle gelmeye başlayabilir. Mukus çoğunlukla sudur — günde 2–2,5 litre su, işareti okunur tutar.",
  cycle_nudge_ovulation_timing_headline: "En çok *önceki iki gün* önemli",
  cycle_nudge_ovulation_timing_body: "Sperm beş güne kadar yaşar; yumurta yalnızca 12–24 saat. Tam güne değil, öncesine odaklan — sıklık, kesin zamanlamadan daha önemli.",
  cycle_nudge_luteal_sleep_headline: "Bu hafta *uykunu* koru",
  cycle_nudge_luteal_sleep_body: "Progesteron vücut ısını yükseltir ve uykuyu böler. Daha serin bir oda ve daha erken yavaşlama, ruh halini beklediğinden fazla dengeler.",
  cycle_nudge_luteal_move_headline: "Bir yürüyüş *girdaptan* iyidir",
  cycle_nudge_luteal_move_body: "Geç luteal dönemdeki düşüşler hormonaldir, hayatın hakkında bir hüküm değil. Yirmi dakika gün ışığı ve hareket, kaydırmaktan daha iyi sıfırlar.",
  cycle_nudge_fertility_follicular_headline: "Pencerene *yaklaşıyorsun*",
  cycle_nudge_fertility_follicular_body: "Östrojen yumurtlamaya doğru yükseliyor. Yumurtlamadan önceki beş gün doğurgan pencerendir — sperm yumurtayı o kadar bekleyebilir.",
  cycle_nudge_fertility_luteal_headline: "Pencere *kapandı*",
  cycle_nudge_fertility_luteal_body: "Yumurta yalnızca 12–24 saat yaşar, bu yüzden döngünün bu kısmında şans düşüktür. Test yaptıysan ya da zamanladıysan, şimdi sadece beklemek kalıyor.",
  cycle_nudge_fertility_menstruation_headline: "*Yepyeni* bir döngü başlıyor",
  cycle_nudge_fertility_menstruation_body: "Birinci gün saati sıfırlar. Bir sonraki doğurgan pencerene yaklaşık iki hafta var — açılmadan önce dinlenip hazırlanmak için sakin bir süre.",
  cycle_nudge_reflect_mood_headline: "Bugün nasıl *hissediyorsun*?",
  cycle_nudge_reflect_mood_body: "Hızlı bir ruh hali kaydı zamanla resmi tamamlar — birkaç döngü kaydettiğinde evrelere göre örüntüleri görmek kolaylaşır.",
  cycle_nudge_reflect_symptom_headline: "Bugün *bir şey* fark ettin mi?",
  cycle_nudge_reflect_symptom_body: "Kramp, göğüslerde hassasiyet, baş ağrısı? Belirtileri kaydetmek, senin ve doktorunun sana özgü olanı fark etmesine yardımcı olur.",
  cycle_nudge_reflect_energy_headline: "*Enerjin* nasıl?",
  cycle_nudge_reflect_energy_body: "Enerji adetten önce doğal olarak düşer. Bugün not etmek, kendi ritmine karşı koymak yerine ona göre plan yapmana yardımcı olur.",
  cycle_nudge_nutrition_luteal_headline: "*Magnezyuma* uzan",
  cycle_nudge_nutrition_luteal_body: "Bitter çikolata, badem, kabak çekirdeği ve muz, döngünün ikinci yarısında krampları hafifletir ve ruh halini dengeler. Atıştırma isteğini yumuşatmak için karmaşık karbonhidratlarla birleştir.",
  cycle_nudge_nutrition_ovulation_headline: "*Yumurtayı* besle",
  cycle_nudge_nutrition_ovulation_body: "Antioksidan açısından zengin besinler — orman meyveleri, yeşil yapraklılar, kuruyemişler — yumurtayı destekler. Çinko (kabak çekirdeği, nohut) en çok yumurtlama çevresinde önemlidir.",
  cycle_nudge_edu_menstruation_headline: "Adetin *ilk* gündür",
  cycle_nudge_edu_menstruation_body: "Döngünün birinci günü, lekelenme değil gerçek kanamanın ilk günüdür. Tüm tahminler buradan sayılır — bu yüzden doğru kaydetmek her şeyi keskinleştirir.",
  cycle_nudge_edu_follicular_headline: "Bir folikül *kazanır*",
  cycle_nudge_edu_follicular_body: "Her döngüde birkaç folikül büyümeye başlar, ama genellikle yalnızca biri olgunlaşıp yumurta salar. Bu seçimi yükselen östrojen yürütür.",
  cycle_nudge_edu_ovulation_headline: "*36 saatlik* bir olay",
  cycle_nudge_edu_ovulation_body: "Yumurtlamanın kendisi kısadır — LH artışı yaklaşık 24–36 saat içinde salınımı tetikler. LH çubukları bu yüzden salınımı değil artışı yakalamak için zamanlanır.",
  cycle_nudge_edu_luteal_headline: "*İki haftalık* bekleyiş",
  cycle_nudge_edu_luteal_body: "Luteal evre dikkat çekici derecede sabittir — döngü uzunluğundan bağımsız olarak genellikle 12–14 gün. Döngü farklarının çoğu bu evreden değil, ilk yarıdan gelir.",
