  dataTrans_subtitle: "sade bir dille",
  dataTrans_intro: "Bize hassas bilgilerini emanet ediyorsun. Tam olarak neyi, neden topladığımız — ve en az bunun kadar önemlisi, onlarla asla neler yapmayacağımız — burada.",
  dataTrans_sectionCollect: "Ne Topluyoruz ve Neden",
  dataTrans_healthTitle: "Sağlık ve döngü verileri",
  dataTrans_healthBody: "Regl, belirtiler, hamilelik haftaları, kilo ve ruh hali — yalnızca takibini, içgörülerini ve Grandma'nın rehberliğini sağlamak için kullanılır. Hepsi senin kalır.",
  dataTrans_childTitle: "Çocukların bilgileri",
  dataTrans_childBody: "Adlar, doğum tarihleri, büyüme, beslenme, uyku ve tıbbi kayıtlar — çocuğunun yolculuğunu kişiselleştirmek ve seçtiğin bakım çevresiyle paylaşmak için kullanılır.",
  dataTrans_accountTitle: "Hesap bilgileri",
  dataTrans_accountBody: "E-postan ve girişin, hesabını güvende tutmak ve verilerini cihazlar arasında eşitlemek için kullanılır. Başka hiçbir şey için değil.",
  dataTrans_aiTitle: "Grandma ile sohbetler",
