  help_q_modes: "Yolculuk modları nedir?",
  help_a_modes: "grandma.app bulunduğun döneme uyum sağlar: Döngü (döngünü takip etmek ya da hamile kalmaya çalışmak), Hamilelik, Çocuklar (0–5 yaş) ve Menopoz. Her yolculuk ana ekranını, kaydettiklerini ve Grandma'nın rehberliğini değiştirir.",
