  help_a_invite: "Ayarlar → Bakım Çevresi → Davet et. Eşine, bakıcına veya büyükanne ya da büyükbabana güvenli bir bağlantı gönder. Onlar tam olarak senin seçtiğin izinlerle katılır.",
  help_q_permissions: "Bakıcıların ne gördüğünü denetleyebilir miyim?",
  help_a_permissions: "Evet. Her bakıcının senin belirlediğin izinleri vardır — kimin kayıtları ve sağlık kayıtlarını görüp ekleyebileceğine sen karar verirsin. Erişimi istediğin zaman değiştirebilir veya kaldırabilirsin.",
  help_q_grandma: "Grandma kim?",
  help_a_grandma: "Grandma, Claude tarafından desteklenen yapay zeka yol arkadaşındır. Sorularını yolculuğunun bağlamıyla yanıtlar ve gece gündüz sıcak, pratik rehberlik sunar.",
  help_q_medical: "Grandma'nın önerileri tıbbi tavsiye midir?",
  help_a_medical: "Hayır. Grandma şefkatli ve eğitici rehberlik sunar — tanı veya tedavi değil. Tıbbi kaygılarında her zaman doktoruna, ebene veya çocuk doktoruna danış.",
  help_q_premium: "Premium neleri içerir?",
  help_a_premium: "Premium sınırsız tarama ve sohbetin, tam içgörülerin ve hatırlatmaların kilidini açar. Aylık veya yıllık abone olabilirsin.",
  help_q_cancel: "Premium'u nasıl iptal ederim?",
  help_a_cancel: "Aboneliğini istediğin zaman uygulama mağazası hesap ayarlarından yönetebilir veya iptal edebilirsin. Premium özellikler faturalandırma döneminin sonuna kadar açık kalır.",
  help_q_dataSafe: "Verilerim güvende mi?",
  help_a_dataSafe: "Evet. Verilerin hem aktarılırken hem saklanırken şifrelenir ve satır düzeyinde güvenlikle korunur; yalnızca sen ve seçtiğin bakım çevresi erişebilir.",
  help_q_sell: "Verilerimi satıyor musunuz?",
  help_a_sell: "Asla. Kişisel verilerini satmayız ve özel sağlık veya çocuk verilerini üçüncü taraf yapay zekayı eğitmek için hiçbir zaman kullanmayız.",
