  guidelines_title: "Topluluk Kuralları",
  guidelines_subtitle: "paylaşmak için nazik bir yer",
  guidelines_intro: "grandma.app, ebeveynlerin birbirine içtenlikle destek olduğu bir alandır. Herkes için güvenli kalması adına birkaç basit kurala uymanı rica ederiz.",
  guidelines_rule1Title: "Nazik ve saygılı ol",
  guidelines_rule1Body: "Burada herkes kendi yolculuğunda. Taciz, zorbalık, nefret söylemi veya kişisel saldırı yok.",
  guidelines_rule2Title: "Gizliliği koru",
  guidelines_rule2Body: "Başkalarının kişisel veya sağlık bilgilerini paylaşma. Kendi ailen hakkında neler açtığına da özen göster.",
  guidelines_rule3Title: "Destek paylaş, tanı koyma",
  guidelines_rule3Body: "Deneyim ve cesaret ver — tıbbi yönlendirme değil. Tıbbi kaygılarda herkesi her zaman doktoruna yönlendir.",
  guidelines_rule4Title: "Spam ve satış yok",
  guidelines_rule4Body: "Topluluğu tanıtım değil, bağ kurmak için kullan. Pazar yeri ilanları akışta değil, takas bölümünde yer alır.",
  guidelines_rule5Title: "Güvenli tut",
  guidelines_rule5Body: "Kendine zarar vermeyi, çocuklara yönelik tehlikeyi veya yasa dışı herhangi bir şeyi teşvik eden içerik olmaz. Bunları kaldırırız ve hesabı askıya alabiliriz.",
  guidelines_sectionReport: "Bir Şey Görürsen",
  guidelines_reportBody: "Bir gönderiyi veya mesajı bildirmek ya da kişiyi engellemek için üzerine uzun bas. Bildirimler gizlidir ve ekibimiz tarafından incelenir. Acil durumda her zaman yerel acil servislerle iletişime geç.",
  guidelines_footer: "Bu kuralları ihlal etmek içeriğin kaldırılmasına veya hesabın askıya alınmasına yol açabilir. Bu topluluğu güvende tuttuğun için teşekkürler.",
