  sw2_leap19_name: "Olaylar",
  sw2_leap19_desc: "Eylemlerin sırayla gerçekleştiğini anlama",
  sw2_leap19_brain: "Bu dönemde bebekler dünyayı tek bir bulanıklık yerine olaylar dizisi olarak fark etmeye başlayabilir. Her eylemin bir başı, ortası ve sonu vardır. Bu, neden-sonuç düşüncesinin başlangıcıdır ve her şeyin birden bu kadar ilgi çekici görünmesinin sebebi de budur.",
  sw2_leap19_tip: "Ce-ee gibi basit neden-sonuç oyunları oyna — bebek olayların tahmin edilebilir sonuçları olduğunu öğreniyor.",
  sw2_leap19_ph0: "Yapışık olabilir, yere bırakılınca ağlayabilir, uykusu bozulabilir. Aynı anda çok şey yeni olduğu için bebek yorgun hissedebilir.",
  sw2_leap19_ph1: "Bebek çoğu zaman her eylemi ardından olanla ilişkilendirmekle meşguldür — itmek, düşürmek, dikkatle izlemek.",
  sw2_leap19_ph2: "Bilerek uzanma ortaya çıkar, nesne sürekliliğinin ilk belirtileri de görülür — bebek düşen şeyleri arar.",
  sw2_leap19_sg0: "Ayrılık kaygısında artış",
  sw2_leap19_sg1: "Çok yapışık",
  sw2_leap19_sg2: "Oyuncak düşünce ağlama",
  sw2_leap19_sg3: "Şekerlemeye direnme",
  sw2_leap19_sg4: "Sürekli etkileşim ister",
  sw2_leap19_sg5: "Rutin bozulunca huzursuz olma",
  sw2_leap19_sk0: "Bilerek uzanıp tutar",
  sw2_leap19_sk1: "Oyuncakları sallar ve vurur",
  sw2_leap19_sk2: "Oyunları tanır",
  sw2_leap19_sk3: "“Yukarı” ve “aşağı”yı anlar",
  sw2_leap19_sk4: "Hareket eden nesneleri gözüyle takip eder",
  sw2_leap19_sk5: "Sürprizlere güler",
  sw2_leap19_ac0: "Ce-ee ve saklambaç oyunları",
  sw2_leap19_ac1: "Topu ileri geri yuvarlama",
  sw2_leap19_ac2: "Basit neden-sonuç oyuncakları (bas = ses)",
  sw2_leap19_ac3: "Günlük rutinleri adım adım anlat",
  sw2_leap5_name: "Değişen duyular",
  sw2_leap5_desc: "Bebek duyuların daha zengin bir dünyasını keşfeder",
  sw2_leap5_brain: "Bu dönemde bebeğin duyularıyla çok daha fazla ayrıntı algılamaya başlayabilir: daha net görüntüler, daha zengin sesler, vücutta yeni hisler. Hem yoğun hem harika olabilir.",
  sw2_leap5_ph0: "Daha çok ağlama, yapışma ve huzursuz uyku sık görülür. Bebek çok sayıda yeni duyusal bilgi alıyor olabilir.",
  sw2_leap5_ph1: "Bebek pek çok yeni görüntü ve ses alıyor. Huzursuzluk yatışmadan önce zirve yapabilir.",
  sw2_leap5_ph2: "Yeni duyusal farkındalık filizlenir: daha uzun uyanık dönemler ve daha bilinçli bakışlar fark edersin.",
  sw2_leap5_sg0: "Normalden çok ağlar",
  sw2_leap5_sg1: "Sürekli emmek ister",
  sw2_leap5_sg2: "Yatıştırması daha zor",
  sw2_leap5_sg3: "Yakınlığı tercih eder",
  sw2_leap5_sg4: "Daha kolay irkilir",
  sw2_leap5_sg5: "Soyulmaktan hoşlanmaz",
  sw2_leap5_sk0: "Işığa ve sese tepki verir",
  sw2_leap5_sk1: "Gözle takip daha akıcı olur",
  sw2_leap5_sk2: "İlk sosyal gülümseme",
  sw2_leap5_sk3: "Daha çok uyanık dönem",
  sw2_leap5_sk4: "Sesine doğru döner",
  sw2_leap5_sk5: "Yüksek kontrastlı desenleri fark eder",
  sw2_leap5_ac0: "Bebeği dışa dönük tutup odayı keşfetmesine izin ver",
  sw2_leap5_ac1: "Yüksek kontrastlı siyah-beyaz kartlar göster",
